fn fetch_journal(context: &CliContext, args: JournalArgs) -> Result<(), CliError> {
	let address = match &args.address {
		Some(value) => CliContext::pubkey("--address", value)?,
		None => {
			let authority = match &args.authority {
				Some(value) => CliContext::pubkey("--authority", value)?,
				None => {
					return Err(CliError::MissingSeed {
						account: "journal".to_string(),
						seed: "--authority".to_string(),
					});
				}
			};
			let seeds: &[&[u8]] = &["compact-journal".as_bytes(), authority.as_ref()];
			Pubkey::find_program_address(seeds, &context.program_address).0
		}
	};
	let data = context.fetch_account(&address)?;
	let value = match compact_accounts_program_client::accounts::Journal::from_bytes(&data) {
		Ok(account) => journal_json(&account),
		Err(error) => {
			return Err(CliError::AccountDecode {
				address: address.to_string(),
				message: error.to_string(),
			});
		}
	};
	print_value(context.json, "journal", &address, &value);
	Ok(())
}

fn journal_json(account: &compact_accounts_program_client::accounts::JournalRef<'_>) -> Value {
	json!({
		"bump": account.bump,
		"authority": account.authority.to_string(),
		"revision": account.revision.get(),
		"featured_entry": account.featured_entry.get().map(|value| value.get()),
		"title": account.title(),
		"entries": account.entries().iter().map(|value| value.get()).collect::<Vec<_>>(),
		"markers": account.markers().iter().copied().collect::<Vec<_>>(),
		"note": account.note(),
	})
}

fn print_value(json_output: bool, name: &str, address: &Pubkey, value: &Value) {
	if json_output {
		println!(
			"{}",
			serde_json::to_string_pretty(value).unwrap_or_default()
		);
		return;
	}

	println!("{name} {address}");
	if let Some(fields) = value.as_object() {
		for (key, value) in fields {
			println!("  {key}: {value}");
		}
	}
}
